@@ -0,0 +1,85 @@
+import { readdirSync } from "node:fs";
+import { join } from "node:path";
+import { obsidianVaultDir } from "../../shared/paths.js";
+import type { CheckResult } from "./types.js";
+
+/**
+ * T-042: test artifacts in the REAL Obsidian vault.
+ *
+ * The suite once wrote session summaries named `<date>-ob-server-<slug>.md` into the developer's real vault: 57 files
+ * before April, 13 more on 2026-08-31, both found by accident (an /end step happened to list `Summaries/`), never by a
+ * check. There is a preventer (`tests/setup-env.ts`, and `obsidianVaultDir()` throws under vitest when it would resolve to
+ * the real vault) and, until this, no detector. `server.test.ts` names its temp project `ob-server-<mkdtemp slug>`, and
+ * `writeSummary` names the note for it.
+ *
+ * LIMIT: a file NAME rule (`ob-server-<slug>.md`, any folder, dot-folders skipped). A test artifact named any other way is
+ * not seen, and nothing is read from inside a note. The vault is the directory `obsidianVaultDir()` resolves.
+ */
+const ARTIFACT = /(^|-)ob-server-[a-z0-9]+\.md$/i;
+const MAX_LISTED = 10;
+
+export interface VaultScan {
+  /** Vault-relative, forward-slash paths of the artifacts. */
+  found: string[];
+  /** `.md` notes examined. */
+  notes: number;
+  /** Directories that could not be listed, with the error code. They are not a clean bill. */
+  unreadable: string[];
+}
+
+type ReadDir = (path: string, options: { withFileTypes: true }) => import("node:fs").Dirent[];
+
+export function scanVaultForTestArtifacts(vaultDir: string, readDir: ReadDir = readdirSync as unknown as ReadDir): VaultScan {
+  const scan: VaultScan = { found: [], notes: 0, unreadable: [] };
+  const walk = (abs: string, rel: string): void => {
+    let entries: import("node:fs").Dirent[];
+    try {
+      entries = readDir(abs, { withFileTypes: true });
+    } catch (err) {
+      scan.unreadable.push(`${rel || "."} (${(err as NodeJS.ErrnoException).code ?? "error"})`);
+      return;
+    }
+    for (const ent of entries) {
+      if (ent.name.startsWith(".")) continue; // .obsidian, .git: not notes
+      const childRel = rel ? `${rel}/${ent.name}` : ent.name;
+      if (ent.isDirectory()) walk(join(abs, ent.name), childRel);
+      else if (ent.isFile() && ent.name.toLowerCase().endsWith(".md")) {
+        scan.notes += 1;
+        if (ARTIFACT.test(ent.name)) scan.found.push(childRel);
+      }
+    }
+  };
+  walk(vaultDir, "");
+  scan.found.sort();
+  return scan;
+}
+
+export function checkVaultPollution(_projectRoot: string, vaultDir?: string): CheckResult {
+  const name = "vault-pollution";
+  let dir: string;
+  try {
+    dir = vaultDir ?? obsidianVaultDir();
+  } catch (err) {
+    return { name, report: true, severity: "skip", message: `not checked: the vault path could not be resolved (${(err as Error).message.split("\n")[0]})` };
+  }
+  const shown = dir.replace(/\\/g, "/");
+  try {
+    readdirSync(dir);
+  } catch (err) {
+    const code = (err as NodeJS.ErrnoException).code ?? "error";
+    return { name, report: true, severity: "skip", message: `not checked: no readable vault at ${shown} (${code}), so ob-server-* artifacts were not looked for. This is not a pass.` };
+  }
+  const scan = scanVaultForTestArtifacts(dir);
+  const unreadable = scan.unreadable.length > 0 ? `; ${scan.unreadable.length} director${scan.unreadable.length === 1 ? "y" : "ies"} unreadable (${scan.unreadable.join(", ")})` : "; 0 directories unreadable";
+  if (scan.found.length === 0) {
+    return { name, report: true, severity: "pass", message: `0 ob-server-* files in ${scan.notes} .md files under the vault${unreadable}` };
+  }
+  const listed = scan.found.slice(0, MAX_LISTED).join("; ");
+  const more = scan.found.length > MAX_LISTED ? `; +${scan.found.length - MAX_LISTED} more` : "";
+  return {
+    name,
+    report: true,
+    severity: "warn",
+    message: `${scan.found.length} ob-server-* file(s) in the vault at ${shown} (of ${scan.notes} .md files): ${listed}${more}. These are test artifacts written outside isolation; delete them with Aaron's approval${unreadable}`,
+  };
+}
diff --git a/open-brain/tests/pipelines/sync/vault-pollution.test.ts b/open-brain/tests/pipelines/sync/vault-pollution.test.ts
new file mode 100644
index 00000000..f089109e
--- /dev/null
+++ b/open-brain/tests/pipelines/sync/vault-pollution.test.ts
@@ -0,0 +1,83 @@
+import { describe, it, expect, afterAll } from "vitest";
+import { mkdirSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { checkVaultPollution, scanVaultForTestArtifacts } from "../../../src/pipelines/sync/vault-pollution.js";
+
+/**
+ * T-042: vault pollution had a preventer (the isolation in tests/setup-env.ts and the throw in obsidianVaultDir) and no
+ * detector. The 13 files named ob-server-<slug>.md that the suite wrote into the real vault were found by accident, at
+ * /end, while listing Summaries/. This counts them.
+ */
+const made: string[] = [];
+const vault = (): string => {
+  const d = mkdtempSync(join(tmpdir(), "t042-vault-"));
+  made.push(d);
+  return d;
+};
+afterAll(() => {
+  for (const d of made) rmSync(d, { recursive: true, force: true, maxRetries: 3, retryDelay: 50 });
+});
+const put = (root: string, rel: string, body = "test\n"): void => {
+  const p = join(root, ...rel.split("/"));
+  mkdirSync(join(p, ".."), { recursive: true });
+  writeFileSync(p, body);
+};
+
+describe("checkVaultPollution — T-042", () => {
+  it("VP-1: a seeded vault warns with the count and the paths", () => {
+    const v = vault();
+    put(v, "Summaries/2026-08-31-ob-server-cz4uxz.md");
+    put(v, "Summaries/2026-08-31-ob-server-abc123.md");
+    put(v, "Checkpoints/deep/ob-server-q.md");
+    put(v, "Summaries/2026-09-01-real-session.md");
+    const r = checkVaultPollution("/unused", v);
+    expect(r.name).toBe("vault-pollution");
+    expect(r.severity).toBe("warn");
+    expect(r.report).toBe(true);
+    expect(r.message).toContain("3 ob-server-* file(s) in the vault");
+    for (const p of ["Summaries/2026-08-31-ob-server-cz4uxz.md", "Summaries/2026-08-31-ob-server-abc123.md", "Checkpoints/deep/ob-server-q.md"]) expect(r.message).toContain(p);
+    expect(r.message).not.toContain("real-session");
+  });
+
+  it("VP-2: a clean vault passes, and says how many notes it looked at", () => {
+    const v = vault();
+    put(v, "Summaries/2026-09-01-real-session.md");
+    put(v, "Experiences/a.md");
+    put(v, ".obsidian/workspace.json", "{}");
+    const r = checkVaultPollution("/unused", v);
+    expect(r.severity).toBe("pass");
+    expect(r.report).toBe(true);
+    expect(r.message).toBe("0 ob-server-* files in 2 .md files under the vault; 0 directories unreadable");
+  });
+
+  it("VP-3: an absent vault is 'not checked', which is neither a pass nor a warning", () => {
+    const missing = join(vault(), "does-not-exist");
+    const r = checkVaultPollution("/unused", missing);
+    expect(r.severity).toBe("skip");
+    expect(r.message).toContain("not checked");
+    expect(r.message).toContain(missing.replace(/\\/g, "/"));
+  });
+
+  it("VP-4: a directory that cannot be read is counted, and a clean-looking scan says so", () => {
+    const v = vault();
+    put(v, "Summaries/a.md");
+    put(v, "Locked/ob-server-hidden.md");
+    const flaky = ((p: string, o: unknown) => {
+      if (String(p).replace(/\\/g, "/").endsWith("/Locked")) throw Object.assign(new Error("EACCES"), { code: "EACCES" });
+      return readdirSync(p, o as never);
+    }) as never;
+    const scan = scanVaultForTestArtifacts(v, flaky);
+    expect(scan.found).toEqual([]);
+    expect(scan.unreadable).toEqual(["Locked (EACCES)"]);
+    expect(scan.notes).toBe(1);
+  });
+
+  it("VP-5: only .md files with the ob-server- slug count; a folder or a similar name does not", () => {
+    const v = vault();
+    put(v, "Summaries/my-ob-server-notes.txt");
+    put(v, "Summaries/server-ob.md");
+    put(v, "ob-server-folder/readme.md");
+    expect(checkVaultPollution("/unused", v).severity).toBe("pass");
+  });
+});

