+  it("VP-1: a seeded vault warns with the count and the paths", () => {
+    const v = vault();
+    put(v, "Summaries/2026-08-31-ob-server-cz4uxz.md");
+    put(v, "Summaries/2026-08-31-ob-server-abc123.md");
