+    name,
+    report: true,
+    severity: "warn",
+    message: `${scan.found.length} ob-server-* file(s) in the vault at ${shown} (of ${scan.notes} .md files): ${listed}${more}. These are test artifacts written outside isolation; delete them with Aaron's approval${unreadable}`,
+  };
+}
