+  const d = mkdtempSync(join(tmpdir(), "t042-vault-"));
+  made.push(d);
+  return d;
+};
+afterAll(() => {
+  for (const d of made) rmSync(d, { recursive: true, force: true, maxRetries: 3, retryDelay: 50 });
+});
+const put = (root: string, rel: string, body = "test\n"): void => {
+  const p = join(root, ...rel.split("/"));
